// migrateV050PG — v0.32.27 — define strftime() PG function so the
// existing SQLite-style SQL (strftime('%s','now')) works unchanged
// on PostgreSQL. The function ignores the format arg (always '%s'
// in skygate's queries) and just returns Unix-epoch seconds via
// EXTRACT(EPOCH FROM now()).
//
// Why not rewrite every query? Because strftime appears inline in
// 12+ SQL strings across internal/db/{queries,node_owner_map,
// secrets,telegram_login_tokens,integrations}.go. Defining the
// function once is 1 migration instead of 12 line edits. And
// SQLite 3.38+ also has strftime (and SQLite < 3.38 will continue
// to work since strftime is its native form), so the function
// doesn't break the SQLite path either — it just never gets called
// there (different SQL backend).
//
// 2026-08-04: v0.33.1 — also create the headscale_acl_rules
// table. The pre-fix V050PG was generated by port_migrations_pg.py
// from the v0.32.x source and only emitted the strftime function
// — the headscale_acl_rules table CREATE (added in v0.33.0 by
// porting migrateV050 to PG) was silently dropped by the
// generator. The fix: add the full PG port of migrateV050
// (headscale_acl_rules + idx_headscale_acl_enabled) below the
// strftime function. The pre-fix /admin/headscale/acl page
// returned http.StatusInternalServerError ("relation headscale_acl_rules does not exist")
// until this landed; now the page renders.
func migrateV050PG(d *sql.DB) error {
	stmts := []string{
		`CREATE OR REPLACE FUNCTION strftime(format text, ts text) RETURNS bigint AS $$
			SELECT EXTRACT(EPOCH FROM now())::bigint
		$$ LANGUAGE SQL IMMUTABLE`,
		`CREATE TABLE IF NOT EXISTS headscale_acl_rules (
			id                  TEXT    PRIMARY KEY,
			rule_json           TEXT    NOT NULL,
			fingerprint         TEXT    NOT NULL,
			label               TEXT    NOT NULL DEFAULT '',
			created_at          BIGINT  NOT NULL DEFAULT (strftime('%s', 'now')::bigint),
			created_by_user_id  INTEGER NOT NULL DEFAULT 0,
			enabled             INTEGER NOT NULL DEFAULT 1,
			UNIQUE(fingerprint, enabled)
		)`,
		`CREATE INDEX IF NOT EXISTS idx_headscale_acl_enabled
			ON headscale_acl_rules(enabled, created_at DESC)`,
	}
	for _, s := range stmts {
		if _, err := d.Exec(s); err != nil {
			return fmt.Errorf("v0.50: %w", err)
		}
	}
	return nil
}

