// migrateV054PG — v0.33.1.39 — Issue 4 technical user.
//
// Same purpose as migrateV054 (SQLite): create the 'infra'
// portal_user row (a system account for skygate-host-* +
// exit-node + subnet-router devices). The corresponding
// headscale user is provisioned at startup by
// ensureInfraUser in cmd/skygate/main.go.
//
// 2026-08-10 v0.33.1.41 #2: uses the reserved id=99
// (system user) to avoid collision with low-id auto-
// assigned values in fresh test DBs. See migrateV054
// (SQLite) for the full rationale. The PG version
// generates a random bcrypt hash for the password_hash
// column (NOT NULL constraint) — same shape as the
// SQLite version, just with $1, $2 placeholders.
func migrateV054PG(d *sql.DB) error {
	var n int
	if err := d.QueryRow(
		`SELECT count(*) FROM portal_users WHERE username = $1`,
		"infra",
	).Scan(&n); err != nil {
		return fmt.Errorf("v0.54: check infra: %w", err)
	}
	if n > 0 {
		return nil
	}
	// bcrypt hash of the literal "infra-never-logs-in-via-web-2026-08-10"
	// — pre-computed so we don't pull golang.org/x/crypto/bcrypt
	// into the PG build path. The 'infra' user is never meant
	// to log in; the hash just ensures bcrypt comparison fails
	// fast if anyone tries.
	const infraHash = "$2a$10$xe4ygoIks1PTpz0aO1jhKeUWTvj2bYQRgoSZE9fyKp6GR8dx7d8oa"
	if _, err := d.Exec(
		`INSERT INTO portal_users (id, username, password_hash, is_admin) VALUES (99, $1, $2, 0) ON CONFLICT (username) DO NOTHING`,
		"infra", infraHash,
	); err != nil {
		return fmt.Errorf("v0.54: insert infra: %w", err)
	}
	return nil
}

// migrateV056PG — v1.3.19.2 follow-up (B125) — UNIQUE INDEX on
// device_rules natural key. Closes the SELECT-then-INSERT race
// in sync.go:432, 512 (auto-add of /32 rules from DNS resolution)
