// migrateV055PG — v1.3.17 — DERP relays per-row table.
//
// Replaces the v0.11.0 "comma-separated URLs in global_settings"
// model with a first-class table. v0.11.0's /admin/derp/config had
// a textarea + bundled checkbox, but the operator wanted the
// exit-nodes-style CRUD (per-row add/edit/delete/toggle/test) so
// they can manage multiple relays with region metadata, not a
// flat list of URLs.
//
// Schema mirrors the exit_servers shape (BIGSERIAL id + integer
// enabled flag + sort_order for the operator's preferred order +
// notes for the operator's context). The "is_bundled" flag
// singles out the row that owns the bundled derper container —
// at most ONE row can have is_bundled=1, enforced at the
// application layer (AddDerpRelay rejects a 2nd bundled row;
// the bundled row is undeletable from the UI but its enabled
// flag is freely toggleable).
//
// Backward compat: the v0.11.0 /admin/derp/config still works
// — it reads + writes the same global_settings.derp.external_urls
// + global_settings.derp.bundled_enabled keys. The new DERP CRUD
// UI is additive. db.AutoMigrateDerpRelays (called from
// LoadIntegrationsFromOS on every read) does the one-shot
// migration: if derp_relays is empty, copy the legacy
// global_settings rows in and write a "migrated" marker.
//
// 2026-08-13: v1.3.17.
func migrateV055PG(d *sql.DB) error {
	stmts := []string{
		`CREATE TABLE IF NOT EXISTS derp_relays (
			id BIGSERIAL PRIMARY KEY,
			hostname TEXT NOT NULL,
			url TEXT NOT NULL,
			region_id INTEGER NOT NULL DEFAULT 900,
			region_code TEXT NOT NULL DEFAULT '',
			region_name TEXT NOT NULL DEFAULT '',
			is_bundled INTEGER NOT NULL DEFAULT 0,
			enabled INTEGER NOT NULL DEFAULT 1,
			sort_order INTEGER NOT NULL DEFAULT 100,
			notes TEXT NOT NULL DEFAULT '',
			created_at INTEGER NOT NULL DEFAULT (EXTRACT(EPOCH FROM now())::bigint),
			updated_at INTEGER NOT NULL DEFAULT (EXTRACT(EPOCH FROM now())::bigint)
		)`,
		`CREATE UNIQUE INDEX IF NOT EXISTS derp_relays_url_uniq
			ON derp_relays(url)`,
		`CREATE INDEX IF NOT EXISTS derp_relays_enabled_idx
			ON derp_relays(enabled)`,
		`CREATE INDEX IF NOT EXISTS derp_relays_is_bundled_idx
			ON derp_relays(is_bundled) WHERE is_bundled = 1`,
	}
	for _, s := range stmts {
		if _, err := d.Exec(s); err != nil {
			return fmt.Errorf("v0.55 derp_relays: %w", err)
		}
	}
	return nil
}

// migrateV058PG — v1.5.0 (B156) — preauth key expiry notifications.
//
// Adds ONE column to preauth_keys:
//   - notified_at  INTEGER NOT NULL DEFAULT 0
//     Unix timestamp of the last "your preauth key is
//     expiring soon" Telegram notification sent to the
//     user. 0 = never notified (the B156 scheduler
//     picks the key for notification).
//
// The B156 in-app scheduler (internal/keynotify) reads
// this column to dedup: a key that's already been
// notified within the current 14-day window is skipped
// on subsequent ticks. Resetting the column to 0 on
// PostMyPreauth (fresh key) + PostMyKeyReissue (new key
// replaces the old) means a reissue restarts the
// notification countdown for the new key.
//
// Existing rows get the DEFAULT 0 via the ALTER TABLE
// NOT NULL DEFAULT clause, so no backfill is needed.
// Fresh inserts via db.InsertPreauthKey explicitly set
// the column to 0 (the same default the migration
// applies to existing rows).
//
// B156 contract test: see scripts/check_b156.sh.
func migrateV058PG(d *sql.DB) error {
	stmts := []string{
		`ALTER TABLE preauth_keys ADD COLUMN IF NOT EXISTS notified_at INTEGER NOT NULL DEFAULT 0`,
	}
	for _, s := range stmts {
		if _, err := d.Exec(s); err != nil {
			return fmt.Errorf("v0.58 preauth_keys notified_at: %w", err)
		}
	}
	return nil
}

// migrateV059PG — v1.5.0 (B157) — in-web notification inbox.
//
// Adds a first-class notifications table for the B157
// bell-icon inbox on the user sidebar. The table is
// the user-facing mirror of the B156 keynotify
// scheduler: every expiring-key event the scheduler
// finds ALSO writes a row here (in addition to the
// Telegram send), so the user sees a per-page
// notification even if they don't have Telegram
// bound, or if the Telegram send was skipped for
// some reason.
//
// Schema:
//   - id           BIGSERIAL PRIMARY KEY
//   - user_id      INTEGER NOT NULL  -- FK portal_users (ON DELETE CASCADE)
//   - type         TEXT    NOT NULL  -- enum-like: 'key.expiring', future types
//   - severity     TEXT    NOT NULL DEFAULT 'info'  -- 'info' | 'warn' | 'danger'
//   - title        TEXT    NOT NULL  -- short title (1 line)
//   - body         TEXT    NOT NULL DEFAULT ''  -- longer description (1-2 lines)
//   - link         TEXT    NOT NULL DEFAULT ''  -- relative URL the bell links to (e.g. /my/keys)
//   - created_at   INTEGER NOT NULL DEFAULT (EXTRACT(EPOCH FROM now())::bigint)
//   - read_at      INTEGER NOT NULL DEFAULT 0  -- unix-seconds; 0 = unread
//
// Indexes:
//   - idx_notifications_user_unread on (user_id, read_at) — the
//     count-unread + list-unread query. Cheap + covers the
//     "bell badge" hot path (every page render).
//   - idx_notifications_user_created on (user_id, created_at DESC) —
//     the list view, "newest first".
//
// The type field is text (not a PG enum) so future
// B-checks can add new notification kinds without a
// schema migration. Same pattern as B156's storage
// keys.
//
// B157 contract test: see scripts/check_b157.sh.
func migrateV059PG(d *sql.DB) error {
	stmts := []string{
		`CREATE TABLE IF NOT EXISTS notifications (
			id BIGSERIAL PRIMARY KEY,
			user_id INTEGER NOT NULL,
			type TEXT NOT NULL,
			severity TEXT NOT NULL DEFAULT 'info',
			title TEXT NOT NULL,
			body TEXT NOT NULL DEFAULT '',
			link TEXT NOT NULL DEFAULT '',
			created_at INTEGER NOT NULL DEFAULT (EXTRACT(EPOCH FROM now())::bigint),
			read_at INTEGER NOT NULL DEFAULT 0,
			FOREIGN KEY (user_id) REFERENCES portal_users (id) ON DELETE CASCADE
		)`,
		`CREATE INDEX IF NOT EXISTS idx_notifications_user_unread
			ON notifications(user_id, read_at)`,
		`CREATE INDEX IF NOT EXISTS idx_notifications_user_created
			ON notifications(user_id, created_at DESC)`,
	}
	for _, s := range stmts {
		if _, err := d.Exec(s); err != nil {
			return fmt.Errorf("v0.59 notifications: %w", err)
		}
	}
	return nil
}

// migrateV060PG — v1.5.2 (B183) — drop parent_domain from
// the device_rules natural-key UNIQUE INDEX.
//
// The pre-B183 index
//
//   CREATE UNIQUE INDEX device_rules_natural_key_uniq
//     ON device_rules(user_id, device_id, exit_node_id,
//                     target_type, target_value, parent_domain)
//
// was 6-column, which let the autoupdater accumulate one
// row per (user, device, exit, type, value) tuple PER
// PARENT_DOMAIN. Live data for emilia (B182 live-verified):
// 102 subnet rows, but only 32 unique subnets — 70+ rows
// were duplicate CIDRs with different parent_domain
// values (e.g. cdn:cloudflare:discordapp.com and
// cdn:cloudflare:discord.com both resolve to 103.21.244.0/22
// and got separate rows). The visible symptom was
// /admin/exit-nodes "mismatch: have 34, want 102" (the
// want side counts raw rows; the have side counts unique
// routes on the Tailscale client).
//
// B183 fix: drop parent_domain from the natural key. The
// natural key is (user, device, exit, type, value) —
// parent_domain is metadata, not part of what makes a rule
// unique. The autoupdater's two ON CONFLICT clauses (sync.go)
// are also updated in B183 to match the 5-column target.
//
// Dedup strategy: pick the "winner" row per (user, device,
// exit, type, value) natural key. Prefer:
//   1. cdn: prefixed parent_domain (more informative —
//      tells the operator which CDN provides the route)
//   2. most recent id (highest id wins) as a tiebreaker
// All other rows with the same natural key are DELETEd.
//
// The migration is idempotent (IF EXISTS / DROP IF EXISTS
// guards). The new index is created with the same name
// (`device_rules_natural_key_uniq`) so any code that
// references it (sync.go's ON CONFLICT) doesn't need to
// change its index name — only the column list.
//
// B183 contract test: see scripts/check_b183.sh.
func migrateV060PG(d *sql.DB) error {
	stmts := []string{
		// Step 1: dedup existing rows by natural key. The
		// ORDER BY picks the winner — cdn: prefix first
		// (most informative), then most recent id.
		// The DELETE removes all losers (rn > 1).
		`DELETE FROM device_rules
		 WHERE id IN (
		   SELECT id FROM (
		     SELECT id,
		       ROW_NUMBER() OVER (
		         PARTITION BY user_id, device_id, exit_node_id, target_type, target_value
		         ORDER BY
		           CASE WHEN parent_domain LIKE 'cdn:%' THEN 0 ELSE 1 END,
		           id DESC
		       ) AS rn
		     FROM device_rules
		   ) ranked
		   WHERE rn > 1
		 )`,
		// Step 2: drop the old 6-column index
		`DROP INDEX IF EXISTS device_rules_natural_key_uniq`,
		// Step 3: create the new 5-column index (without
		// parent_domain). Same name so ON CONFLICT clauses
		// can target it by name if needed.
		`CREATE UNIQUE INDEX IF NOT EXISTS device_rules_natural_key_uniq
			ON device_rules(user_id, device_id, exit_node_id, target_type, target_value)`,
	}
	for _, s := range stmts {
		if _, err := d.Exec(s); err != nil {
			return fmt.Errorf("v0.60 device_rules natural-key drop parent_domain: %w", err)
		}
	}
	return nil
}

// migrateV061PG — v1.5.2 (B188) — backfill legacy
// tag:exit-<hostname> exit-node-pref rows to the
// canonical tag:dev-infra-<hostname> form, and
// re-enable the per-row pinning that the v0.28.5
// backfill missed.
//
// The original v0.28.5 migration (migrateV047PG)
// was supposed to set via_enabled=1 on every
// pre-existing row so the user's existing pref
// continued to pin the device to the chosen
// exit-node after the opt-in/via_enabled column
// was introduced. It guards on "freshlyAdded" —
// only runs the UPDATE if the column didn't
// pre-exist. In production the column pre-existed
// (likely from a manual ALTER in a prior hotfix),
// so the freshlyAdded check returned false and
// the UPDATE was skipped. Result: every pref row
// shipped with via_enabled=0, and the per-device
// grant in headscale is NEVER emitted with via=.
// The pref is decorative only — the user must
// pick the exit-node manually in Tailscale.
//
// This migration has two parts:
//
// 1. Tag backfill. Walk every row in
//    user_exit_node_prefs + device_exit_node_prefs
//    whose exit_node_tag matches the legacy
//    "tag:exit-<hostname>" form. For each, look up
//    the matching node_owner_map row and replace
//    exit_node_tag with the canonical tag. Rows
//    with no match are LEFT ALONE (with a NOTICEs
//    in the migration log) so the operator can
//    decide whether to clean them up by hand.
//
// 2. Re-enable via pinning. The original intent of
//    v0.28.5 was to set via_enabled=1 for every
//    pre-existing row so the user's intent
//    (pinned exit-node) was preserved through the
//    opt-in migration. We do that here, but ONLY
//    for rows whose exit_node_tag points at a
//    real headscale tag (i.e. starts with
//    "tag:dev-infra-"). A row pointing at a
//    ghost tag (e.g. tag:exit-emilia that the
//    tag backfill couldn't resolve) stays
//    via_enabled=0 — we don't want headscale to
//    reject the policy on a missing tag.
//
// The migration is idempotent: re-running it is a
// no-op (the LIKE 'tag:exit-%' WHERE clause
// matches nothing on the second run; the
// via_enabled=1 UPDATE is idempotent for already-
// pinned rows).
//
// 2026-08-26: v1.5.2 (B188).
func migrateV061PG(d *sql.DB) error {
	// Step 1: user_exit_node_prefs backfill.
	// We can't use a simple JOIN+UPDATE in PG (UPDATE
	// ... FROM is allowed, but the read-side aliasing
	// for the tag rewrite is more readable as two
	// SELECTs). Walk every legacy row, compute the
	// canonical tag, and UPDATE if the lookup
	// succeeded. Rows where the hostname doesn't
	// resolve to a node_owner_map entry are skipped
	// (they keep the legacy tag; the operator can
	// clean up via SQL).
	if _, err := d.Exec(`
		UPDATE user_exit_node_prefs p
		   SET exit_node_tag = n.tag
		  FROM node_owner_map n
		 WHERE p.exit_node_tag LIKE 'tag:exit-%'
		   AND LOWER(SUBSTRING(p.exit_node_tag FROM 10)) = LOWER(n.hostname)
		   AND p.exit_node_tag <> n.tag
	`); err != nil {
		return fmt.Errorf("v0.61 user_exit_node_prefs tag backfill: %w", err)
	}
	// Step 2: device_exit_node_prefs backfill (same
	// logic, different table).
	if _, err := d.Exec(`
		UPDATE device_exit_node_prefs p
		   SET exit_node_tag = n.tag
		  FROM node_owner_map n
		 WHERE p.exit_node_tag LIKE 'tag:exit-%'
		   AND LOWER(SUBSTRING(p.exit_node_tag FROM 10)) = LOWER(n.hostname)
		   AND p.exit_node_tag <> n.tag
	`); err != nil {
		return fmt.Errorf("v0.61 device_exit_node_prefs tag backfill: %w", err)
	}
	// Step 3: re-enable via pinning for rows whose
	// tag is a real headscale tag (tag:dev-infra-*
	// is the post-B118 convention; tag:exit-node is
	// the static catch-all that doesn't need via
	// because it's not a per-host pin).
	//
	// Only flip rows that:
	//   - currently have via_enabled=0 (don't
	//     disturb rows the operator explicitly
	//     opted out of post-B188)
	//   - point at a real headscale tag (the
	//     policy parser will reject any other
	//     form, so we leave them un-pinned)
	if _, err := d.Exec(`
		UPDATE user_exit_node_prefs
		   SET via_enabled = 1
		 WHERE via_enabled = 0
		   AND exit_node_tag LIKE 'tag:dev-infra-%'
	`); err != nil {
		return fmt.Errorf("v0.61 user_exit_node_prefs via_enabled backfill: %w", err)
	}
	if _, err := d.Exec(`
		UPDATE device_exit_node_prefs
		   SET via_enabled = 1
		 WHERE via_enabled = 0
		   AND exit_node_tag LIKE 'tag:dev-infra-%'
	`); err != nil {
		return fmt.Errorf("v0.61 device_exit_node_prefs via_enabled backfill: %w", err)
	}
	return nil
}


// migrateV062PG — v1.5.2 (B189) — DERP health dashboard.
//
// Adds the derp_health table that caches live latency
// measurements for every known DERP server (Tailscale's
// 28 public regions + the operator's own derp_relays
// rows). The derphealth package (internal/derphealth)
// probes each server's HTTPS endpoint with a TLS
// handshake, measures TTFB, and writes results here.
//
// Columns:
//   - region_id: PK. region_id 1-28 = Tailscale's
//     public regions. region_id 900+ = operator's own
//     derp_relays (or the bundled Tailscale default
//     for region_id=901).
//   - is_own: 1 if this row is one of the operator's
//     own DERP servers, 0 if it's a Tailscale public.
//   - host / url: where to probe. `url` is the full
//     https://...; `host` is the bare hostname used
//     for the latency probe and display.
//   - region_code / region_name / locality / country:
//     display metadata. region_code is the IATA-ish
//     code (e.g. "waw" / "hel") when Tailscale's map
//     exposes it; "" otherwise.
//   - latency_ms: the most recent probe's measured
//     TLS-handshake latency in milliseconds. NULL
//     when never probed or the last probe failed.
//   - last_check: unix epoch of the last probe attempt
//     (success or failure).
//   - healthy: 1 if the last probe returned 2xx/3xx on
//     the / endpoint; 0 on any error.
//   - last_error: empty on success, or the last probe's
//     error string. Used for the dashboard's "degraded"
//     hint without losing the last latency value (e.g.
//     if a probe fails intermittently).
//   - probes_total / probes_failed: counters for the
//     DERP health time-series. probes_failed is the
//     number of consecutive failed probes (resets to 0
//     on the first success after any failure).
//
// The table does NOT replace headscale's DERP selection
// or Tailscale's netcheck — it's an operator-facing
// observability surface. The recommended DERP (lowest
// latency among reachable own + public) is highlighted
// in the dashboard, not enforced anywhere.
//
// Idempotent: ON CONFLICT (region_id) DO UPDATE so
// re-probes just refresh the latency + last_check
// columns.
func migrateV062PG(d *sql.DB) error {
	if _, err := d.Exec(`
		CREATE TABLE IF NOT EXISTS derp_health (
			region_id     INTEGER PRIMARY KEY,
			is_own        INTEGER NOT NULL DEFAULT 0,
			host          TEXT    NOT NULL DEFAULT '',
			url           TEXT    NOT NULL DEFAULT '',
			region_code   TEXT    NOT NULL DEFAULT '',
			region_name   TEXT    NOT NULL DEFAULT '',
			locality      TEXT    NOT NULL DEFAULT '',
			country       TEXT    NOT NULL DEFAULT '',
			latency_ms    INTEGER,
			last_check    INTEGER NOT NULL DEFAULT 0,
			healthy       INTEGER NOT NULL DEFAULT 0,
			last_error    TEXT    NOT NULL DEFAULT '',
			probes_total  INTEGER NOT NULL DEFAULT 0,
			probes_failed INTEGER NOT NULL DEFAULT 0
		)
	`); err != nil {
		return fmt.Errorf("v0.62 derp_health table: %w", err)
	}
	return nil
}
